from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Baseline doitgen kernel.
# For each (r, q) we compute:
#   A[r, q, p] = sum_s A[r, q, s] * C4[s, p]
@proc
def kernel_doitgen_base(
    nr: size,
    nq: size,
    np: size,
    A: DATA_TYPE[nr, nq, np] @ DRAM,
    C4: DATA_TYPE[np, np] @ DRAM,
    sum: DATA_TYPE[np] @ DRAM,
):
    # Note: the argument `sum` is provided by the C driver for scratch
    # space but is not required here. We instead use a private local
    # buffer to make outer loops parallelizable and improve locality.

    for r in seq(0, nr):
        for q in seq(0, nq):

            # Private accumulation buffer for this (r, q).
            # Using a local buffer keeps the working set small and
            # avoids cross-iteration interference when we parallelize
            # the outer loop over r.
            sum_local: DATA_TYPE[np]

            # Initialize the accumulation buffer.
            for p in seq(0, np):
                sum_local[p] = 0.0

            # Matrix-vector style multiply:
            #   sum_local[p] += A[r, q, s] * C4[s, p]
            # We hoist A[r, q, s] into a scalar so it is loaded once
            # per (r, q, s) and reused across the inner p loop.
            for s in seq(0, np):
                a_rqs: DATA_TYPE
                a_rqs = A[r, q, s]
                for p in seq(0, np):
                    sum_local[p] += a_rqs * C4[s, p]

            # Write the result back into A.
            for p in seq(0, np):
                A[r, q, p] = sum_local[p]


# ---------------------------------------------------------------------------
# Scheduling / optimization: improve locality and expose parallelism.
# ---------------------------------------------------------------------------

kernel_doitgen_sched = kernel_doitgen_base

# 1) Lift the sum_local allocation out of the q-loop but keep it inside
#    the r-loop. This keeps one scratch buffer per r-iteration, reused
#    across all q, while still allowing different r-iterations to have
#    private storage.
sum_alloc = kernel_doitgen_sched.find("sum_local : _")
kernel_doitgen_sched = lift_alloc(kernel_doitgen_sched, sum_alloc, n_lifts=1)

# 2) Parallelize the outermost loop over r.
#    Different r-iterations:
#      - write to disjoint slices A[r, :, :],
#      - use their own sum_local buffer (after the lift above),
#      - read C4 read-only.
#    This is therefore safe to parallelize (maps to OpenMP in C).
r_loop = kernel_doitgen_sched.find_loop("r")
kernel_doitgen_sched = parallelize_loop(kernel_doitgen_sched, r_loop)

# 3) Expose the scheduled version under the name expected by the C driver.
kernel_doitgen = rename(kernel_doitgen_sched, "kernel_doitgen")
